sys_ui_page.client_script:
// FULL TAB SWITCHING
function switchTab(tabKey) {
  document.querySelectorAll('.nav-btn').forEach(btn => btn.classList.remove('active'));
  document.querySelectorAll('.tab-view').forEach(view => view.classList.remove('active'));

  var tabMap = {
    'dashboard': { btn: 'btnNavDashboard', view: 'view-dashboard' },
    'customer-orders': { btn: 'btnNavCustomerOrders', view: 'view-customer-orders' },
    'production': { btn: 'btnNavProduction', view: 'view-production' },
    'schedule': { btn: 'btnNavSchedule', view: 'view-schedule' },
    'inventory': { btn: 'btnNavInventory', view: 'view-inventory' },
    'procurement': { btn: 'btnNavProcurement', view: 'view-procurement' },
    'suppliers': { btn: 'btnNavSuppliers', view: 'view-suppliers' },
    'alerts': { btn: 'btnNavAlerts', view: 'view-alerts' },
    'forecasting': { btn: 'btnNavForecasting', view: 'view-forecasting' },
    'digital-twin': { btn: 'btnNavDigitalTwin', view: 'view-digital-twin' }
  };

  var target = tabMap[tabKey] || tabMap['customer-orders'];
  var btnEl = document.getElementById(target.btn);
  var viewEl = document.getElementById(target.view);

  if (btnEl) btnEl.classList.add('active');
  if (viewEl) viewEl.classList.add('active');

  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function filterOrders(term) {
  var rows = document.querySelectorAll('#ordersTableBody tr');
  rows.forEach(function(row) {
    var text = row.innerText.toLowerCase();
    row.style.display = text.includes(term.toLowerCase()) ? '' : 'none';
  });
}

function runDigitalTwinSim() {
  document.getElementById('simResultsContainer').style.display = 'block';
  alert('Simulation completed: Alternative A achieves +12% On-Time Delivery recovery by routing PO-101 to WC-ADD-503.');
}

function applyDigitalTwinPlan() {
  alert('Schedule updated in ServiceNow: PO-101 dispatched to WC-ADD-503. Machine breakdown mitigated!');
  switchTab('production');
}

function refreshData() {
  alert('Real-time data synchronized with ServiceNow dev445579.');
}
